/* Public source index only. No automatic bug-status conclusions or account access. */
(function(root){
 'use strict';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const safe=u=>{try{const x=new URL(u);return x.protocol==='https:'&&x.hostname==='steamcommunity.com'&&!x.username&&!x.password&&!x.port&&/^\/app\/3079210\/discussions\/[01]\/\d+\/$/.test(x.pathname)&&[...x.searchParams.keys()].every(k=>['ctp','l'].includes(k))?x.href:'';}catch(_){return '';}};
 const time=v=>{const d=new Date(v);return v&&Number.isFinite(+d)?d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Not yet recorded';};
 const num=v=>Number.isSafeInteger(v)&&v>=0?v:0;
 let data=null,filter='all',order='newest';
 function unavailable(){const host=document.getElementById('staffResponses');if(host)host.innerHTML='<h2>Staff responses in tracked discussions</h2><p role="status">Discussion coverage could not be loaded. This does not mean there are no new staff responses.</p>';}
 function render(value){
  if(value!==undefined)data=value;
  const host=document.getElementById('staffResponses');if(!host)return;
  if(!data||data.schema_version!==1||!Array.isArray(data.threads)){unavailable();return;}
  const stale=!data.last_attempt_at||!Number.isFinite(Date.parse(data.last_attempt_at))||Date.now()-Date.parse(data.last_attempt_at)>30*3600000;
  const complete=data.state==='complete'&&!stale&&num(data.threads_total)>0&&num(data.threads_complete)===num(data.threads_total);
  const states={complete:'Fully scanned',partial:'Partially scanned',unavailable:'Could not scan'};
  const change={baseline:'Historical baseline',new_reply:'New reply since monitoring began',edited:'Wording change detected',historical_discovery:'Older reply newly found'};
  const reasons={access_restricted:'Access restricted',deferred_access_restricted:'Deferred after access restriction',rate_limited:'Rate limited',deferred_rate_limited:'Deferred after rate limit',robots_restricted:'Automated access restricted',page_budget:'Page limit reached',run_budget:'Time/request budget reached',thread_changed_during_scan:'Thread changed during collection'};
  let entries=data.threads.filter(t=>safe(t.url)).flatMap(t=>(t.replies||[]).filter(r=>safe(r.response_url)).map(r=>({...r,thread:t,activity_at:r.source_edited_at||r.published_at})));
  entries=entries.filter(r=>filter!=='changes'||['new_reply','edited'].includes(r.change_kind));
  entries=HLLVDates.sorted(entries,'activity_at',order);
  const cards=entries.map(r=>'<details class="response-entry"><summary><time datetime="'+esc(r.activity_at)+'">'+(r.source_edited_at?'Edited ':'Posted ')+esc(time(r.activity_at))+'</time><strong>'+esc(r.thread.title)+'</strong><span>'+esc(r.author_label)+' · '+esc(r.source_category)+'</span></summary><div><p class="response-small">Originally posted '+esc(time(r.published_at))+' · '+esc(change[r.change_kind]||'Previously collected response')+(r.change_kind==='edited'?' · Change detected '+esc(time(r.last_changed_at)):'')+(r.source_edited_at?' · Source edit date '+esc(time(r.source_edited_at)):'')+'</p>'+(r.excerpt?'<p>Response opening: “'+esc(r.excerpt)+'”</p>':'')+'<p class="response-small">'+(r.observed_this_run?'Staff identity and original response checked in this pass.':'Previously collected; not reverified in this pass. Absence is not proof of deletion.')+' Last seen: '+esc(time(r.last_seen_at))+'.</p><a href="'+esc(safe(r.response_url))+'" target="_blank" rel="noopener noreferrer">Read this staff response ↗</a><p class="response-small">Linked tracked issues: '+(r.thread.tracked_issue_ids||[]).filter(id=>/^HLLV-\d+$/.test(id)).map(id=>'<a href="#'+esc(id)+'">'+esc(id)+'</a>').join(' · ')+'. A thread link does not establish that this particular response addresses every linked issue.</p></div></details>');
  const gaps=data.threads.filter(t=>t.state!=='complete');
  host.innerHTML='<div class="feed-heading"><div><span class="section-kicker">Reply-level source monitoring</span><h2>Staff responses in tracked discussions</h2></div></div><p class="response-coverage" role="status" data-complete="'+complete+'">'+(stale?'Discussion check overdue. ':'')+num(data.threads_complete)+' of '+num(data.threads_total)+' monitored discussions fully scanned in the last pass. '+(complete?'':'Coverage is incomplete or out of date. ')+'Attempted '+esc(time(data.last_attempt_at))+'.</p><p class="response-small">Existing tracked Steam threads only—not every Steam discussion or affiliate channel. Attributable replies, not reviewed changes to bug status.</p><p class="response-small">Last complete pass: '+esc(time(data.last_complete_at))+'. '+num(data.identities_pending)+' staff identities awaiting verification.</p><div class="response-tools"><label>Show <select id="responseFilter"><option value="all" '+(filter==='all'?'selected':'')+'>All collected responses</option><option value="changes" '+(filter==='changes'?'selected':'')+'>New or edited since monitoring began</option></select></label><label>Date order <select id="responseOrder"><option value="newest" '+(order==='newest'?'selected':'')+'>Newest first</option><option value="oldest" '+(order==='oldest'?'selected':'')+'>Oldest first</option></select></label></div><div id="staffResponseList">'+(cards.length?cards.slice(0,3).join('')+(cards.length>3?'<details class="feed-more"><summary>More staff responses ('+(cards.length-3)+')</summary>'+cards.slice(3).join('')+'</details>':''):'<p>'+(filter==='changes'?'No new or edited qualifying response has been recorded since this monitor began. Older baseline responses remain under All collected responses.':'No verified staff responses have been collected for this scope yet.')+(complete?'':' Incomplete coverage prevents an all-clear conclusion.')+'</p>')+'</div><details class="response-details"><summary>Coverage by discussion'+(gaps.length?' · '+gaps.length+' incomplete':'')+'</summary>'+data.threads.filter(t=>safe(t.url)).map(t=>'<div class="response-thread"><a href="'+esc(safe(t.url))+'" target="_blank" rel="noopener noreferrer">'+esc(t.title)+'</a><p>'+esc(states[t.state]||'Not checked')+' · '+num(t.pages_checked)+' of '+(t.pages_expected===null?'unknown':num(t.pages_expected))+' pages; '+num(t.comments_seen)+' of '+(t.comments_expected===null?'unknown':num(t.comments_expected))+' comments checked.'+(t.failure_kind?' '+esc(reasons[t.failure_kind]||t.failure_kind.replaceAll('_',' '))+'.':'')+'</p><p class="response-small">Last complete scan: '+esc(time(t.last_complete_at))+'</p>'+(t.identities_pending||[]).map(a=>safe(a.evidence_url)?'<p class="response-small">Staff account awaiting verification: <a href="'+esc(safe(a.evidence_url))+'" target="_blank" rel="noopener noreferrer">Review source identity ↗</a></p>':'').join('')+'</div>').join('')+'<p class="response-small">Old replies collected during setup are a historical baseline, not today’s news. New identities need review; display names and quotes inside player comments do not establish staff authority. Source-response monitoring does not grant site moderators developer authority.</p></details>';
  host.querySelector('#responseFilter').onchange=e=>{filter=e.target.value;render();host.querySelector('#responseFilter').focus({preventScroll:true});};
  host.querySelector('#responseOrder').onchange=e=>{order=e.target.value;render();host.querySelector('#responseOrder').focus({preventScroll:true});};
 }
 root.HLLVResponses=Object.freeze({render,unavailable});
})(globalThis);
